{
  "name": "Giniaz College",
  "description": "An educational app offering in-depth courses on business, leadership, technology, and personal development. Users can generate lesson content and convert it to audio for automatic download."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import type { Course } from './types';
import { COURSES } from './constants';
import Header from './components/Header';
import CourseCard from './components/CourseCard';
import CourseDetail from './components/CourseDetail';

const App: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  const handleSelectCourse = (course: Course) => {
    setSelectedCourse(course);
  };

  const handleBack = () => {
    setSelectedCourse(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-slate-900 to-black text-gray-200">
      <Header />
      <main className="container mx-auto p-4 md:p-8">
        {selectedCourse ? (
          <CourseDetail course={selectedCourse} onBack={handleBack} />
        ) : (
          <div>
            <h2 className="text-3xl font-bold mb-2 text-center text-cyan-400">Karibu Giniaz College</h2>
            <p className="text-lg text-center mb-8 text-gray-400">Chagua somo ili uanze kujifunza.</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {COURSES.map((course) => (
                <CourseCard 
                  key={course.id} 
                  course={course} 
                  onClick={() => handleSelectCourse(course)} 
                />
              ))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Course {
  id: string;
  title: string;
  description: string;
  icon: React.ComponentType<{ className?: string }>;
}

export interface Lesson {
  title: string;
  content: string;
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Lesson } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const lessonsSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      title: {
        type: Type.STRING,
        description: 'The title of the lesson, in Swahili.',
      },
      content: {
        type: Type.STRING,
        description: 'The detailed content of the lesson, in Swahili, with a minimum of 200 words.',
      },
    },
    required: ['title', 'content'],
  },
};

export const generateLessons = async (courseTitle: string): Promise<Lesson[]> => {
  try {
    const prompt = `Tafadhali tengeneza masomo 12 yenye uzito mkubwa na maelezo ya kina kwa lugha ya Kiswahili kuhusu mada hii: "${courseTitle}". Kila somo liwe na kichwa cha habari na maudhui yenye angalau maneno 200. Maudhui yawe ya kuelimisha na yenye manufaa makubwa kwa mwanafunzi.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: lessonsSchema,
      },
    });

    const jsonString = response.text.trim();
    const lessons = JSON.parse(jsonString);

    if (Array.isArray(lessons) && lessons.length > 0) {
      return lessons;
    }
    throw new Error('Received invalid lesson format from API.');

  } catch (error) {
    console.error("Error generating lessons:", error);
    throw new Error("Failed to generate lessons. Please try again.");
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Tafadhali somea maandishi haya kwa sauti ya utulivu na ya kuelimisha: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        return base64Audio || null;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate audio.");
    }
};

import React from 'react';
import { BookOpenIcon } from './icons';

const Header: React.FC = () => {
  return (
    <header className="bg-gray-900/50 backdrop-blur-sm shadow-lg shadow-cyan-500/10 sticky top-0 z-50">
