export default CourseCard;

import React, { useState, useEffect, useCallback } from 'react';
import type { Course, Lesson } from '../types';
import { generateLessons } from '../services/geminiService';
import LessonContent from './LessonContent';
import { ArrowLeftIcon } from './icons';

interface CourseDetailProps {
  course: Course;
  onBack: () => void;
}

const CourseDetail: React.FC<CourseDetailProps> = ({ course, onBack }) => {
  const [lessons, setLessons] = useState<Lesson[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedLessonIndex, setSelectedLessonIndex] = useState<number | null>(null);

  const fetchLessons = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedLessons = await generateLessons(course.title);
      setLessons(fetchedLessons);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  }, [course.title]);

  useEffect(() => {
    fetchLessons();
  }, [fetchLessons]);

  const handleSelectLesson = (index: number) => {
    setSelectedLessonIndex(index);
  };

  const handleCloseLesson = () => {
    setSelectedLessonIndex(null);
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="text-center py-10">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-400 mx-auto"></div>
            <p className="mt-4 text-gray-400">Tunaandaa masomo...</p>
        </div>
      );
    }

    if (error) {
      return <div className="text-center py-10 text-red-400 bg-red-900/20 rounded-lg p-4">
        <p>Tatizo limetokea: {error}</p>
        <button onClick={fetchLessons} className="mt-4 px-4 py-2 bg-cyan-600 hover:bg-cyan-500 rounded-md">Jaribu Tena</button>
      </div>;
    }

    if (lessons) {
        return (
            <div className="space-y-4">
                {lessons.map((lesson, index) => (
                    <div
                        key={index}
                        onClick={() => handleSelectLesson(index)}
                        className="bg-gray-800 p-4 rounded-lg cursor-pointer border border-gray-700 hover:bg-gray-700/50 hover:border-cyan-500 transition-colors"
                    >
                        <h4 className="text-lg font-semibold text-cyan-400">Somo {index + 1}: {lesson.title}</h4>
                    </div>
                ))}
            </div>
        );
    }

    return null;
  };

  if (selectedLessonIndex !== null && lessons) {
      return <LessonContent lesson={lessons[selectedLessonIndex]} onBack={handleCloseLesson} lessonNumber={selectedLessonIndex + 1} />
  }

  return (
    <div>
      <button 
        onClick={onBack} 
        className="flex items-center mb-6 text-cyan-400 hover:text-cyan-300 transition-colors"
      >
        <ArrowLeftIcon className="h-5 w-5 mr-2" />
        Rudi kwenye Masomo
      </button>
      <h2 className="text-3xl font-bold mb-2 text-white">{course.title}</h2>
      <p className="text-gray-400 mb-8">Masomo 12 yenye uzito mkubwa.</p>
      {renderContent()}
    </div>
  );
};

export default CourseDetail;

import React, { useState } from 'react';
import type { Lesson } from '../types';
import { generateSpeech } from '../services/geminiService';
import { DownloadIcon, AudioWaveIcon, ArrowLeftIcon } from './icons';

interface LessonContentProps {
  lesson: Lesson;
  onBack: () => void;
  lessonNumber: number;
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

const LessonContent: React.FC<LessonContentProps> = ({ lesson, onBack, lessonNumber }) => {
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [audioError, setAudioError] = useState<string | null>(null);

  const handleGenerateAndDownload = async () => {
    setIsGeneratingAudio(true);
    setAudioError(null);
    try {
      const base64Audio = await generateSpeech(lesson.content);
      if (base64Audio) {
        const audioBytes = decode(base64Audio);
        const blob = new Blob([audioBytes], { type: 'audio/mpeg' });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        const safeTitle = lesson.title.replace(/[^a-zA-Z0-9]/g, '_');
        a.download = `Somo_${lessonNumber}_${safeTitle}.mp3`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      } else {
        throw new Error("Hakuna sauti iliyotengenezwa.");
      }
    } catch (err) {
      setAudioError(err instanceof Error ? err.message : 'An unknown error occurred during audio generation.');
    } finally {
      setIsGeneratingAudio(false);
    }
  };

  return (
    <div className="bg-gray-800/50 rounded-lg p-6 border border-gray-700">
        <button 
            onClick={onBack} 
            className="flex items-center mb-6 text-cyan-400 hover:text-cyan-300 transition-colors"
        >
            <ArrowLeftIcon className="h-5 w-5 mr-2" />
            Rudi kwenye Orodha ya Masomo
        </button>
        <h3 className="text-2xl font-bold text-cyan-400 mb-4">Somo {lessonNumber}: {lesson.title}</h3>
        <div className="prose prose-invert max-w-none text-gray-300 whitespace-pre-wrap leading-relaxed">
            {lesson.content}
        </div>
        <div className="mt-8 border-t border-gray-700 pt-6">
            <button
                onClick={handleGenerateAndDownload}
                disabled={isGeneratingAudio}
                className="w-full sm:w-auto flex items-center justify-center px-6 py-3 bg-cyan-600 text-white font-semibold rounded-lg
                           hover:bg-cyan-500 disabled:bg-gray-600 disabled:cursor-not-allowed
                           transition-all duration-300"
            >
                {isGeneratingAudio ? (
                    <>
                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Inatengeneza Sauti...
                    </>
                ) : (
                    <>
                        <DownloadIcon className="h-5 w-5 mr-2" />
                        Pakua Sauti
                    </>
                )}
            </button>
            {audioError && <p className="text-red-400 mt-4">{audioError}</p>}
        </div>
    </div>
  );
};

export default LessonContent;

