import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Lesson } from '../types';

// FIX: Per coding guidelines, the API key is obtained directly from environment variables and assumed to be valid. The check for its existence is removed.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const lessonsSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      title: {
        type: Type.STRING,
        description: 'The title of the lesson, in Swahili.',
      },
      content: {
        type: Type.STRING,
        description: 'The detailed content of the lesson, in Swahili, with a minimum of 300 words.',
      },
    },
    required: ['title', 'content'],
  },
};

export const generateLessons = async (courseTitle: string): Promise<Lesson[]> => {
  try {
    const prompt = `Tafadhali tengeneza mtaala wa masomo 12 kwa kozi ya "${courseTitle}". Mtaala huu uwe na mpangilio kutoka kiwango cha msingi (beginner) hadi cha juu (advanced), kama inavyofundishwa chuoni. Kila somo liwe na kichwa cha habari kinachoendana na kiwango chake, na maudhui ya kina (angalau maneno 300) yenye maelezo, mifano, na dhana muhimu. Lugha iwe ni Kiswahili rasmi na cha kitaaluma.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: lessonsSchema,
      },
    });

    const jsonString = response.text.trim();
    const lessons = JSON.parse(jsonString);

    if (Array.isArray(lessons) && lessons.length > 0) {
      return lessons;
    }
    throw new Error('Received invalid lesson format from API.');

  } catch (error) {
    console.error("Error generating lessons:", error);
    throw new Error("Failed to generate lessons. Please try again.");
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Tafadhali somea maandishi haya kwa sauti ya utulivu na ya kuelimisha: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        return base64Audio || null;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate audio.");
    }
};

import React, { useState, useEffect, useCallback } from 'react';
import type { Course, Lesson } from '../types';
import { generateLessons } from '../services/geminiService';
import LessonContent from './LessonContent';
import Certificate from './Certificate';
import { ArrowLeftIcon, LockClosedIcon, CheckCircleIcon, PlayCircleIcon, TrophyIcon } from './icons';

interface CourseDetailProps {
  course: Course;
  onBack: () => void;
}

const CourseDetail: React.FC<CourseDetailProps> = ({ course, onBack }) => {
  const [lessons, setLessons] = useState<Lesson[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedLessonIndex, setSelectedLessonIndex] = useState<number | null>(null);

  const [completedLessons, setCompletedLessons] = useState<boolean[]>(() => {
    try {
      const savedProgress = localStorage.getItem(`progress_${course.id}`);
      return savedProgress ? JSON.parse(savedProgress) : Array(12).fill(false);
    } catch (e) {
      console.error("Failed to load progress", e);
      return Array(12).fill(false);
    }
  });

  const [showCertificate, setShowCertificate] = useState(false);

  const fetchLessons = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedLessons = await generateLessons(course.title);
      // Ensure progress array matches lesson count if API returns different number
      if (fetchedLessons.length !== completedLessons.length) {
        setCompletedLessons(Array(fetchedLessons.length).fill(false));
      }
      setLessons(fetchedLessons);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  }, [course.title, completedLessons.length]);

  useEffect(() => {
    fetchLessons();
  }, [fetchLessons]);

  useEffect(() => {
    try {
      localStorage.setItem(`progress_${course.id}`, JSON.stringify(completedLessons));
    } catch (e) {
      console.error("Failed to save progress", e);
    }
  }, [completedLessons, course.id]);

  const handleSelectLesson = (index: number) => {
    const firstUncompleted = completedLessons.findIndex(status => !status);
    if (index === firstUncompleted || completedLessons[index]) {
      setSelectedLessonIndex(index);
    }
  };

  const handleCompleteLesson = (index: number) => {
    const newCompletedLessons = [...completedLessons];
    if (!newCompletedLessons[index]) {
      newCompletedLessons[index] = true;
      setCompletedLessons(newCompletedLessons);
    }
    setSelectedLessonIndex(null);
  };

  const allLessonsCompleted = lessons && lessons.length > 0 && completedLessons.slice(0, lessons.length).every(status => status === true);

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="text-center py-10">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-400 mx-auto"></div>
            <p className="mt-4 text-gray-400">Tunaandaa masomo...</p>
        </div>
      );
    }

    if (error) {
      return <div className="text-center py-10 text-red-400 bg-red-900/20 rounded-lg p-4">
        <p>Tatizo limetokea: {error}</p>
        <button onClick={fetchLessons} className="mt-4 px-4 py-2 bg-cyan-600 hover:bg-cyan-500 rounded-md">Jaribu Tena</button>
      </div>;
    }

    if (lessons) {
      const firstUncompletedIndex = completedLessons.findIndex(status => !status);

      return (
          <div>
            {allLessonsCompleted && (
              <div className="bg-green-900/50 border border-green-500 text-center p-6 rounded-lg mb-8">
                <h3 className="text-2xl font-bold text-green-300">Pongezi! Umekamilisha Kozi!</h3>
                <p className="text-green-400 mt-2">Sasa unaweza kupata cheti chako maalum cha pongezi.</p>
                <button
                  onClick={() => setShowCertificate(true)}
                  className="mt-4 flex items-center justify-center mx-auto px-6 py-3 bg-yellow-500 text-gray-900 font-bold rounded-lg hover:bg-yellow-400 transition-colors"
                >
                  <TrophyIcon className="h-6 w-6 mr-2" />
                  Pata Cheti Chako
                </button>
              </div>
            )}
            <div className="space-y-3">
              {lessons.map((lesson, index) => {
                const isCompleted = completedLessons[index];
                const isNext = index === firstUncompletedIndex;
                const isLocked = !isCompleted && !isNext;

                let statusIcon;
                let cursorClass = isLocked ? 'cursor-not-allowed opacity-60' : 'cursor-pointer';
                let hoverClass = isLocked ? '' : 'hover:bg-gray-700/80';
                let textColor = 'text-gray-400';
                let borderColor = 'border-gray-700';

                if (isCompleted) {
                  statusIcon = <CheckCircleIcon className="h-6 w-6 text-green-400 flex-shrink-0" />;
                  textColor = 'text-gray-300';
                  borderColor = 'hover:border-green-500';
                } else if (isNext) {
                  statusIcon = <PlayCircleIcon className="h-6 w-6 text-cyan-400 flex-shrink-0" />;
                  textColor = 'text-white';
                  borderColor = 'border-cyan-600 hover:border-cyan-400';
                  hoverClass += ' animate-pulse';
                } else { // Locked
                  statusIcon = <LockClosedIcon className="h-6 w-6 text-gray-600 flex-shrink-0" />;
                }

                return (
                  <div
                    key={index}
                    onClick={() => !isLocked && handleSelectLesson(index)}
                    className={`bg-gray-800 p-4 rounded-lg border flex items-center space-x-4 transition-all duration-300 ${cursorClass} ${hoverClass} ${borderColor}`}
                  >
                    {statusIcon}
                    <div className="flex-1">
                      <h4 className={`text-lg font-semibold ${textColor}`}>Somo {index + 1}: {lesson.title}</h4>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
      );
    }
    return null;
  };

  if (showCertificate) {
    return <Certificate courseTitle={course.title} onBack={() => setShowCertificate(false)} />;
  }

  if (selectedLessonIndex !== null && lessons) {
      return <LessonContent lesson={lessons[selectedLessonIndex]} onBack={() => handleCompleteLesson(selectedLessonIndex)} lessonNumber={selectedLessonIndex + 1} />
  }

  return (
    <div>
      <button 
        onClick={onBack} 
        className="flex items-center mb-6 text-cyan-400 hover:text-cyan-300 transition-colors"
      >
        <ArrowLeftIcon className="h-5 w-5 mr-2" />
        Rudi kwenye Masomo
      </button>
      <h2 className="text-3xl font-bold mb-2 text-white">{course.title}</h2>
      <p className="text-gray-400 mb-8">Fuata mtiririko wa masomo 12 ili kukamilisha kozi.</p>
      {renderContent()}
    </div>
  );
};

export default CourseDetail;

