interface LessonContentProps {
  lesson: Lesson;
  onBack: () => void;
  lessonNumber: number;
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

function createWavBlobFromPcm(pcmData: Uint8Array): Blob {
  const sampleRate = 24000;
  const numChannels = 1;
  const bitsPerSample = 16;

  const header = new ArrayBuffer(44);
  const view = new DataView(header);

  const writeString = (offset: number, string: string) => {
    for (let i = 0; i < string.length; i++) {
      view.setUint8(offset + i, string.charCodeAt(i));
    }
  };

  // RIFF header
  writeString(0, 'RIFF');
  view.setUint32(4, 36 + pcmData.length, true);
  writeString(8, 'WAVE');

  // fmt chunk
  writeString(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * numChannels * (bitsPerSample / 8), true);
  view.setUint16(32, numChannels * (bitsPerSample / 8), true);
  view.setUint16(34, bitsPerSample, true);

  // data chunk
  writeString(36, 'data');
  view.setUint32(40, pcmData.length, true);

  return new Blob([header, pcmData], { type: 'audio/wav' });
}


const LessonContent: React.FC<LessonContentProps> = ({ lesson, onBack, lessonNumber }) => {
  const { theme } = useTheme();
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [audioError, setAudioError] = useState<string | null>(null);

  const themeConfig = {
    cyber: {
      accentText: 'text-cyan-400',
      accentTextHover: 'hover:text-cyan-300',
      accentButton: 'bg-cyan-600',
      accentButtonHover: 'hover:bg-cyan-500',
    },
    sunrise: {
      accentText: 'text-amber-300',
      accentTextHover: 'hover:text-amber-200',
      accentButton: 'bg-amber-600',
      accentButtonHover: 'hover:bg-amber-500',
    },
    forest: {
      accentText: 'text-emerald-400',
      accentTextHover: 'hover:text-emerald-300',
      accentButton: 'bg-emerald-600',
      accentButtonHover: 'hover:bg-emerald-500',
    }
  };
  const currentTheme = themeConfig[theme];

  const handleGenerateAndDownload = useCallback(async () => {
    setIsGeneratingAudio(true);
    setAudioError(null);
    try {
      const base64Audio = await generateSpeech(lesson.content);
      if (base64Audio) {
        const audioBytes = decode(base64Audio);
        const blob = createWavBlobFromPcm(audioBytes);
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        const safeTitle = lesson.title.replace(/[^a-zA-Z0-9]/g, '_');
        a.download = `Somo_${lessonNumber}_${safeTitle}.wav`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      } else {
        throw new Error("Hakuna sauti iliyotengenezwa.");
      }
    } catch (err) {
      setAudioError(err instanceof Error ? err.message : 'An unknown error occurred during audio generation.');
    } finally {
      setIsGeneratingAudio(false);
    }
  }, [lesson.content, lesson.title, lessonNumber]);

  useEffect(() => {
    handleGenerateAndDownload();
  }, [handleGenerateAndDownload]);

  return (
    <div className="bg-gray-800/50 rounded-lg p-6 border border-gray-700">
        <button 
            onClick={onBack} 
            className={`flex items-center mb-6 ${currentTheme.accentText} ${currentTheme.accentTextHover} transition-colors`}
        >
            <ArrowLeftIcon className="h-5 w-5 mr-2" />
            Kamilisha Somo & Rudi Kwenye Orodha
        </button>
        <h3 className={`text-2xl font-bold ${currentTheme.accentText} mb-4`}>Somo {lessonNumber}: {lesson.title}</h3>
        <div className="prose prose-invert max-w-none text-gray-300 whitespace-pre-wrap leading-relaxed">
            {lesson.content}
        </div>
        <div className="mt-8 border-t border-gray-700 pt-6">
            <button
                onClick={handleGenerateAndDownload}
                disabled={isGeneratingAudio}
                className={`w-full sm:w-auto flex items-center justify-center px-6 py-3 ${currentTheme.accentButton} text-white font-semibold rounded-lg
                           ${currentTheme.accentButtonHover} disabled:bg-gray-600 disabled:cursor-not-allowed
                           transition-all duration-300`}
            >
                {isGeneratingAudio ? (
                    <>
                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Inapakua Sauti...
                    </>
                ) : (
                    <>
                        <DownloadIcon className="h-5 w-5 mr-2" />
                        Pakua Tena
                    </>
                )}
            </button>
            {audioError && <p className="text-red-400 mt-4">{audioError}</p>}
        </div>
    </div>
  );
};

