  };

  const allLessonsCompleted = lessons && lessons.length > 0 && completedLessons.slice(0, lessons.length).every(status => status === true);

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="text-center py-10">
            <div className={`animate-spin rounded-full h-12 w-12 border-b-2 ${currentTheme.accentBorder} mx-auto`}></div>
            <p className={`mt-4 ${currentTheme.mutedText}`}>Tunaandaa masomo...</p>
        </div>
      );
    }

    if (error) {
      const reInitialize = async () => {
        setIsLoading(true);
        setError(null);
        try {
          const fetchedLessons = await generateLessons(course.title);
          setLessons(fetchedLessons);
          // Re-initialize progress as well
          setCompletedLessons(Array(fetchedLessons.length).fill(false));
        } catch (err) {
          setError(err instanceof Error ? err.message : 'An unknown error occurred.');
        } finally {
          setIsLoading(false);
        }
      }
      return (
        <div className={`text-center py-10 ${currentTheme.errorText} ${currentTheme.errorBg} rounded-lg p-4`}>
          <p>Tatizo limetokea: {error}</p>
          <button onClick={reInitialize} className={`mt-4 px-4 py-2 ${currentTheme.accentButton} ${currentTheme.accentButtonHover} text-white rounded-md`}>Jaribu Tena</button>
        </div>
      );
    }

    if (lessons) {
      const firstUncompletedIndex = completedLessons.findIndex(status => !status);

      return (
          <div>
            {allLessonsCompleted && (
              <div className={`${currentTheme.successBg} border ${currentTheme.successBorder} text-center p-6 rounded-lg mb-8`}>
                <h3 className={`text-2xl font-bold ${currentTheme.successText}`}>Pongezi! Umekamilisha Kozi!</h3>
                <p className={`${currentTheme.successMuted} mt-2`}>Sasa unaweza kupata cheti chako maalum cha pongezi.</p>
                <button
                  onClick={() => setShowCertificate(true)}
                  className="mt-4 flex items-center justify-center mx-auto px-6 py-3 bg-yellow-500 text-gray-900 font-bold rounded-lg hover:bg-yellow-400 transition-colors"
                >
                  <TrophyIcon className="h-6 w-6 mr-2" />
                  Pata Cheti Chako
                </button>
              </div>
            )}
            <div className="space-y-3">
              {lessons.map((lesson, index) => {
                const isCompleted = completedLessons[index];
                const isNext = index === firstUncompletedIndex;
                const isLocked = !isCompleted && !isNext;

                let statusIcon;
                let cursorClass = isLocked ? 'cursor-not-allowed opacity-60' : 'cursor-pointer';
                let hoverClass = isLocked ? '' : currentTheme.hoverBg;
                let lessonTextColor = currentTheme.mutedText;
                let borderColorClass = theme === 'light' ? 'border-gray-200' : 'border-gray-700';

                if (isCompleted) {
                  statusIcon = <CheckCircleIcon className="h-6 w-6 text-green-400 flex-shrink-0" />;
                  lessonTextColor = theme === 'light' ? 'text-gray-800' : 'text-gray-300';
                  borderColorClass += ' hover:border-green-500';
                } else if (isNext) {
                  statusIcon = <PlayCircleIcon className={`h-6 w-6 ${currentTheme.accentText} flex-shrink-0`} />;
                  lessonTextColor = currentTheme.titleText;
                  borderColorClass = `${currentTheme.accentBorderActive} ${currentTheme.accentBorderHover}`;
                  hoverClass += ' animate-pulse';
                } else { // Locked
                  statusIcon = <LockClosedIcon className="h-6 w-6 text-gray-600 flex-shrink-0" />;
                }

                return (
                  <div
                    key={index}
                    onClick={() => !isLocked && handleSelectLesson(index)}
                    className={`${currentTheme.baseBg} p-4 rounded-lg border flex items-center space-x-4 transition-all duration-300 ${cursorClass} ${hoverClass} ${borderColorClass}`}
                  >
                    {statusIcon}
                    <div className="flex-1">
                      <h4 className={`text-lg font-semibold ${lessonTextColor}`}>{lesson.title}</h4>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
      );
    }
    return null;
  };

  if (showCertificate) {
    return <Certificate courseTitle={course.title} onBack={() => setShowCertificate(false)} />;
  }

  if (selectedLessonIndex !== null && lessons) {
      return <LessonContent lesson={lessons[selectedLessonIndex]} onBack={() => handleCompleteLesson(selectedLessonIndex)} lessonNumber={selectedLessonIndex + 1} />
  }

  return (
    <div>
      <button 
        onClick={onBack} 
        className={`flex items-center mb-6 ${currentTheme.accentText} ${currentTheme.accentTextHover} transition-colors`}
      >
        <ArrowLeftIcon className="h-5 w-5 mr-2" />
        Rudi kwenye Masomo
      </button>
      <h2 className={`text-3xl font-bold mb-2 ${currentTheme.titleText}`}>{course.title}</h2>
      <p className={`${currentTheme.mutedText} mb-8`}>Fuata mtiririko wa masomo 12 ili kukamilisha kozi.</p>
      {renderContent()}
    </div>
  );
};

export default CourseDetail;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Lesson } from '../types';

// FIX: Per coding guidelines, the API key is obtained directly from environment variables and assumed to be valid. The check for its existence is removed.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const lessonsSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      title: {
        type: Type.STRING,
        description: 'The title of the lesson, in Swahili.',
      },
      content: {
        type: Type.STRING,
        description: 'The very long and in-depth content of the lesson, in Swahili, with a minimum of 3200 words, suitable for a college-level course.',
      },
    },
    required: ['title', 'content'],
  },
};

export const generateLessons = async (courseTitle: string): Promise<Lesson[]> => {
  try {
    const prompt = `Kama mhadhiri wa chuo kikuu, tengeneza mtaala wa kina wa masomo 12 kwa kozi ya "${courseTitle}" kwa lugha ya Kiswahili. Lengo ni kumpa mwanafunzi maarifa ya kina ("MAARIFA ya kina") yanayolingana na kiwango cha chuo. Kila somo liwe na mpangilio kutoka kiwango cha utangulizi hadi cha juu. Muhimu: Kila somo lazima liwe na maudhui marefu na ya kina sana, yenye angalau maneno 3200. Maudhui hayo yajumuishe maelezo ya kitaaluma, mifano halisi, uchambuzi wa kina (case studies ikiwezekana), na matumizi yake katika ulimwengu halisi. Hakikisha mtiririko wa masomo unamjenga mwanafunzi hatua kwa hatua.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: lessonsSchema,
      },
    });

    const jsonString = response.text.trim();
    const lessons = JSON.parse(jsonString);

    if (Array.isArray(lessons) && lessons.length > 0) {
      return lessons;
    }
    throw new Error('Received invalid lesson format from API.');

  } catch (error) {
    console.error("Error generating lessons:", error);
    throw new Error("Failed to generate lessons. Please try again.");
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Tafadhali somea maandishi haya kwa sauti ya utulivu na ya kuelimisha: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        return base64Audio || null;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate audio.");
    }
};

